  const pd = 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion='+si+'.'+sig;
  return new Promise((resolve,reject) => {
    const req = https.request('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','Content-Length':Buffer.byteLength(pd)}},(res)=>{let d='';res.on('data',c=>d+=c);res.on('end',()=>{try{resolve(JSON.parse(d));}catch(e){reject(e);}});});
    req.on('error',reject);req.write(pd);req.end();
  });
}

// Generic Google Calendar call. Returns {status, body} (body = parsed JSON or null for empty replies like DELETE 204).
function gcal(token, method, path, bodyObj) {
  const bodyStr = bodyObj ? JSON.stringify(bodyObj) : null;
  const headers = {'Authorization':'Bearer '+token};
  if (bodyStr) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = Buffer.byteLength(bodyStr); }
  return new Promise((resolve,reject) => {
    const req = https.request({hostname:'www.googleapis.com',path:`/calendar/v3/calendars/${encodeURIComponent(CAL_ID)}${path}`,method,headers},(res)=>{
      let d='';res.on('data',c=>d+=c);
      res.on('end',()=>{let b=null;if(d){try{b=JSON.parse(d);}catch(e){b={raw:d};}}resolve({status:res.statusCode,body:b});});
    });
    req.on('error',reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

// Send a WhatsApp text via Evolution API. Needs 'http' in NODE_FUNCTION_ALLOW_BUILTIN. Never throws; returns true/false.
async function sendWhatsApp(number, text) {
  let http;
  try { http = require('http'); } catch (e) { return false; }
  const body = JSON.stringify({ number, text });
  for (let attempt = 0; attempt < 2; attempt++) {
