        res.on('data',()=>{});
        res.on('end',()=>resolve(res.statusCode>=200 && res.statusCode<300));
      });
      req.on('timeout',()=>{req.destroy();resolve(false);});
      req.on('error',()=>resolve(false));
      req.write(body);req.end();
    });
    if (ok) return true;
  }
  return false;
}

