  const got = await gcal(token, 'GET', `/events/${encodeURIComponent(event_id)}`);
  if (got.status === 404 || (got.body && got.body.status === 'cancelled')) return 'CANCEL ERROR: Booking not found (already cancelled?). Call find_bookings again.';
  if (got.status !== 200) return `CANCEL ERROR: calendar returned ${got.status}: ${JSON.stringify(got.body)}`;
  const ev = got.body;
  if (!samePhone(phoneOfEvent(ev), client_phone)) return 'CANCEL ERROR: This booking belongs to another client. Do not cancel it.';

  const del = await gcal(token, 'DELETE', `/events/${encodeURIComponent(event_id)}`);
  if (del.status !== 204 && del.status !== 200 && del.status !== 410) return `CANCEL ERROR: calendar returned ${del.status}: ${JSON.stringify(del.body)}. Ask client to contact +598 94 786877.`;

  const info = `${serviceOfEvent(ev)} | ${evDate(ev)} ${evStart(ev)}-${evEnd(ev)}`;
  const sent = await notifyMasters(
